head.script:
let curID = '';
let oldID = '';


// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[linkedDataList > M > getID]<br/>Scope 가 적용된 DataList 모듈의 렌더링 ID 를 반환합니다.",
    "validation" : [
        "반환값으로 렌더링 과정에서 부여된 Scope ID 를 반환합니다.",
        "디자인 시 설정한 DataList 모듈의 ID 가 아닌 렌더링 시 Scope 에 맞게 부여된 ID 를 반환합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    curID = con_ID.getText();

    // 기존 target 있으면 삭제
    if (typeof gdl_org !== 'undefined') {
        $p.data.remove("gdl_org");
    }

    if (typeof target1 !== 'undefined') {
        $p.data.remove("target1");
    }

    if (typeof gridView1 !== 'undefined') {
        gridView1.remove();
    }   

    if (typeof gridView2 !== 'undefined') {
        gridView2.remove();
    }    

    // target 생성
    $c.gcm.createOrginalDataList();

    let grp_comp = document.querySelector('.tc_group_basic');   
    let strTarget = '';
    let strGridView2 = '';
    let strNameSpace = $c.gcm.getNameSpace();

    strTarget += '<w2:linkedDataList ' + strNameSpace + ' id="'+ curID +'" bind="gdl_org">'
    strTarget += '<w2:condition type="filter"><![CDATA[cat1==ref("data:gdl_org.cat1")]]></w2:condition>'
    strTarget += '<w2:condition type="sort"><![CDATA[]]></w2:condition>'
    strTarget += '</w2:linkedDataList>'  

    // target 생성
    $p.data.create(strTarget);

    let arrResult = $p.data.getAllDataCollection("object");
    scwin[curID] = arrResult[arrResult.length-1];

    oldID = curID;

    // gridView 생성
    $c.gcm.createOriginalGridView();

    strGridView2 += '<w2:gridView ' + strNameSpace + ' autoFit="allColumn" checkAllType="false" dataList="data:'+curID+'" rowStatusVisible="true" sortable="true" style="width:500px; height:200px;" focusMode="row" syncRowPositionOption="style">'
    strGridView2 += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>'
    strGridView2 += '<w2:header style="" id="header1">'
    strGridView2 += '<w2:row style="" id="row1">'
    strGridView2 += '<w2:column width="70" style="" inputType="text" id="column4" value="cat1"></w2:column>'
    strGridView2 += '<w2:column width="70" style="" inputType="text" id="column3" value="cat2"></w2:column>'
    strGridView2 += '<w2:column width="70" style="" inputType="text" id="column2" value="label"></w2:column>'
    strGridView2 += '<w2:column width="70" style="" inputType="text" id="column1" value="value"></w2:column>'
    strGridView2 += '</w2:row>'
    strGridView2 += '</w2:header>'
    strGridView2 += '<w2:gBody style="" id="gBody1">'
    strGridView2 += '<w2:row style="" id="row2">'
    strGridView2 += '<w2:column width="70" style="" inputType="text" id="cat1" value=""></w2:column>'
    strGridView2 += '<w2:column width="70" style="" inputType="text" id="cat2" value=""></w2:column>'
    strGridView2 += '<w2:column width="70" style="" inputType="text" id="label" value=""></w2:column>'
    strGridView2 += '<w2:column width="70" style="" inputType="text" id="value" value=""></w2:column>'
    strGridView2 += '</w2:row>'
    strGridView2 += '</w2:gBody>'
    strGridView2 += '</w2:gridView>'

    // target 생성
    scwin["gridView2"] = await $p.dynamicCreate(
        "gridView2",
        "gridView",
        strGridView2,
        grp_comp
    );
}



scwin.btn_getID_onclick = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("getID : " + scwin[curID].getID());  
};
